begin;
-- The JSON snapshot is generated from the reviewed application catalog.
create table dcc_private.selection_catalog(singleton boolean primary key default true check(singleton),data jsonb not null);
insert into dcc_private.selection_catalog(data) values ($selection_catalog${"races":[{"id":"human","name":"Human","page":135,"earth":true,"size":4,"stats":{"strength":2,"intelligence":2,"constitution":2,"dexterity":2,"charisma":2},"skills":{},"dr":0,"defenses":{},"requirement":"none","notes":"At floor end, one Skill at Rank 9 or less advances with Advantage. Spend Favor for Con-based DR when damaged; once daily use a non-Passive untrained Utility Skill as Rank 2; once per floor remove a Debuff, including Injuries. Timing and these conditional benefits are resolved at the table. Future level-gain Favor is automatic."},{"id":"amazonian","name":"Amazonian","page":129,"earth":true,"size":4,"stats":{"strength":6,"intelligence":0,"constitution":0,"dexterity":3,"charisma":0},"skills":{"bow":2,"endurance":2,"pugilism":2},"dr":2,"defenses":{},"requirement":"physical-skill-5","notes":"Requires an existing Strength- or Dexterity-based Skill at Rank 5+. Receive a free Weapon Training Guild coupon each floor; issue and use coupons at the table. Optional gender/species limits are adjudicated by the GM."},{"id":"crocodilian","name":"Crocodilian","page":131,"earth":true,"size":5,"stats":{"strength":4,"intelligence":0,"constitution":3,"dexterity":0,"charisma":0},"skills":{"pugilism":2,"powerful-strike":2},"dr":3,"defenses":{},"requirement":"none","notes":"Advantage when physically menacing someone with Intimidate; +1 to Skill Checks for an hour after a full meal; Disadvantage on Charisma-based Checks while Fatigued. Conditional effects are resolved at the table."},{"id":"igneous","name":"Igneous","page":135,"earth":true,"size":5,"stats":{"strength":4,"intelligence":-2,"constitution":6,"dexterity":0,"charisma":-2},"skills":{"endurance":1},"dr":3,"defenses":{"Fire":{"resistant":false,"vulnerable":false,"immune":true},"Ice":{"resistant":false,"vulnerable":true,"immune":false}},"requirement":"none","notes":"Once daily double Move for 20 seconds. Action: Con Check to deal 1d8+F Fire, 5ft Burst. No harsh-environment Survival Checks; breathe underwater and burrow. Lose one Health Bar slot on Inventory access (not Hotlist); Disadvantage concealing presence or nature. These actions, costs and conditional effects are manual."},{"id":"pterolykos","name":"Pterolykos","page":141,"earth":false,"size":4,"stats":{"strength":0,"intelligence":0,"constitution":0,"dexterity":2,"charisma":4},"skills":{"bite":3,"performance":3,"tracking":3,"diplomacy":1},"dr":0,"defenses":{},"requirement":"none","notes":"Alien Race: cannot select Earth Classes. Fly for up to 50 seconds per scene; Disadvantage concealing emotion or presence; +1 Popularity on a Charisma Skill Critical Hit. Flight, Popularity and conditional checks are manual."}],"classes":[{"id":"fighter","name":"Boring Ol’ Fighter","page":150,"earthOnly":false,"stats":{"strength":2,"intelligence":0,"constitution":2,"dexterity":0,"charisma":0},"skills":{"dodge":3},"dr":0,"defenses":{},"requirement":"none","choices":[{"id":"weapon","label":"Weapon Skill (+5)","count":1,"bonus":5,"ids":["dagger","longsword","rapier","warhammer","bow","crossbow","shotgun","polearm","quarterstaff","lance","javelin","shuriken","slingshot","improvised-weapons"]},{"id":"support","label":"Two different support Skills (+2 each)","count":2,"bonus":2,"ids":["aiming","attack-of-opportunity","catcher","shield-block","zone-of-control"]}],"notes":"Access any Weapon Training Guild and receive one free training coupon each floor. Dodge grants a passive Evade Buff and later upgrades; apply passive ability bonuses and coupon rewards at the table."},{"id":"pit-fighter","name":"Pit Fighter","page":150,"earthOnly":true,"stats":{"strength":1,"intelligence":2,"constitution":0,"dexterity":3,"charisma":0},"skills":{"attack-of-opportunity":3,"dirty-fighting":3,"dodge":2,"improvised-weapons":2},"dr":2,"defenses":{},"requirement":"none","choices":[],"notes":"Award a Silver Earth Box with a guaranteed Earth Hobby Potion manually. Dodge/other passive ability effects, interrupt timing, Damage Effect conditions and upgrades remain table-adjudicated."},{"id":"blizzardmancer","name":"Blizzardmancer","page":153,"earthOnly":false,"stats":{"strength":-2,"intelligence":4,"constitution":0,"dexterity":3,"charisma":0},"skills":{"ice-blast":4,"frost-scar":4,"aiming":2},"dr":0,"defenses":{"Ice":{"resistant":true,"vulnerable":false,"immune":false}},"requirement":"none","choices":[],"notes":"May use Aiming for single-target Ice Spells. Spell damage, rank upgrades and conditional Aiming are resolved at the table; casting uses the existing prepared-Spell and Mana workflow."},{"id":"monster-truck-driver","name":"Monster Truck Driver","page":152,"earthOnly":true,"stats":{"strength":-2,"intelligence":-2,"constitution":4,"dexterity":2,"charisma":0},"skills":{"gear-head":3,"driving":3,"pathfinder":3},"dr":0,"defenses":{"Force":{"resistant":true,"vulnerable":false,"immune":false}},"requirement":"driving-5","choices":[],"notes":"Requires Driving Rank 5+. Earth-only Class. Moving in combat can increase the Health Bar threshold based on conveyance Move; on foot requires a prior Move Action. Manual special Action: Floor Rank + Dex, 1d12 Bludgeoning, 2d10+3ft Line; then Fatigued; Critical Fail on Natural 4 or less; 30-hour cooldown; add one die at Ranks 5/10/15. Once per combat when losing 2+ slots, roll 1d2: on 1 attacker loses a slot. Award the Silver Earth Box/Hobby Potion manually."}],"abilities":[{"id":"aiming","name":"Aiming","kind":"skill","stat":null,"passive":true,"advancement":"special","maxRank":15,"manaCost":null,"description":"Passive ranged-attack support. Mark only when applying its Ranks to the qualifying ranged Attack.","reference":"Core Rulebook p. 184","damage":"","range":"","automation":"manual"},{"id":"animal-handling","name":"Animal Handling","kind":"skill","stat":"charisma","passive":false,"advancement":"normal","maxRank":15,"manaCost":null,"description":"Refer to the listed entry for conditions, damage, cooldowns, and Rank upgra