. 199","damage":"","range":"","automation":"manual"},{"id":"tactics","name":"Tactics","kind":"skill","stat":"intelligence","passive":false,"advancement":"normal","maxRank":15,"manaCost":null,"description":"Refer to the listed entry for conditions, damage, cooldowns, and Rank upgrades. Effects are adjudicated at the table.","reference":"Core Rulebook p. 200","damage":"","range":"","automation":"manual"},{"id":"taunt","name":"Taunt","kind":"skill","stat":"charisma","passive":false,"advancement":"normal","maxRank":15,"manaCost":null,"description":"Refer to the listed entry for conditions, damage, cooldowns, and Rank upgrades. Effects are adjudicated at the table.","reference":"Core Rulebook p. 200","damage":"","range":"","automation":"manual"},{"id":"throwing","name":"Throwing","kind":"skill","stat":"strength","passive":false,"advancement":"normal","maxRank":15,"manaCost":null,"description":"Refer to the listed entry for conditions, damage, cooldowns, and Rank upgrades. Effects are adjudicated at the table.","reference":"Core Rulebook p. 200","damage":"","range":"","automation":"manual"},{"id":"toss","name":"Toss","kind":"effect","stat":null,"passive":true,"advancement":"special","maxRank":15,"manaCost":null,"description":"Hand-to-hand Damage Effect. For one attack, mark this effect OR the associated Attack Skill, not both.","reference":"Core Rulebook p. 181","damage":"","range":"","automation":"manual"},{"id":"tracking","name":"Tracking","kind":"skill","stat":"intelligence","passive":false,"advancement":"normal","maxRank":15,"manaCost":null,"description":"Refer to the listed entry for conditions, damage, cooldowns, and Rank upgrades. Effects are adjudicated at the table.","reference":"Core Rulebook p. 201","damage":"","range":"","automation":"manual"},{"id":"unarmed-combat","name":"Unarmed Combat","kind":"attack","stat":"strength","passive":false,"advancement":"normal","maxRank":15,"manaCost":null,"description":"Refer to the listed entry for conditions, damage, cooldowns, and Rank upgrades. Effects are adjudicated at the table.","reference":"Core Rulebook p. 179","damage":"1d4 + Str Bludgeoning","range":"","automation":"manual"},{"id":"vine-porn","name":"Vine Porn","kind":"spell","stat":"constitution","passive":false,"advancement":"normal","maxRank":15,"manaCost":3,"description":"Refer to the listed entry for conditions, damage, cooldowns, and Rank upgrades. Effects are adjudicated at the table.","reference":"Core Rulebook p. 213","damage":"1d4 + Con Piercing","range":"20 feet","automation":"manual"},{"id":"warhammer","name":"Warhammer","kind":"attack","stat":"strength","passive":false,"advancement":"normal","maxRank":15,"manaCost":null,"description":"Refer to the listed entry for conditions, damage, cooldowns, and Rank upgrades. Effects are adjudicated at the table.","reference":"Core Rulebook p. 178","damage":"1d10 + Str Bludgeoning","range":"","automation":"manual"},{"id":"wrasslin","name":"Wrasslin’","kind":"attack","stat":"strength","passive":false,"advancement":"special","maxRank":15,"manaCost":null,"description":"Hand-to-hand Attack. When adding a Damage Effect, mark this Skill OR the Damage Effect for that attack, never both. Resolve damage and Rank upgrades at the table.","reference":"Core Rulebook p. 179","damage":"1d4 + Str Bludgeoning","range":"","automation":"manual"},{"id":"diplomacy","name":"Diplomacy","kind":"skill","stat":"charisma","passive":false,"advancement":"normal","maxRank":15,"manaCost":null,"description":"Mediate between opposing parties with an Int-Opposed Check against the side with higher Int Mod. Resolve conditions and upgrades at the table.","reference":"Core Rulebook p. 189","damage":"","range":"","automation":"manual"},{"id":"attack-of-opportunity","name":"Attack of Opportunity","kind":"skill","stat":null,"passive":true,"advancement":"none","maxRank":15,"manaCost":null,"description":"Passive Interrupt. Requires a one-handed melee weapon with reach no greater than 5ft. Spend an Action to attack a foe leaving an adjacent space except via Step. Timing and upgrades are manual.","reference":"Core Rulebook p. 185","damage":"","range":"","automation":"manual"},{"id":"dirty-fighting","name":"Dirty Fighting","kind":"effect","stat":null,"passive":true,"advancement":"special","maxRank":15,"manaCost":null,"description":"Pugilism/Wrasslin’ Damage Effect. Apply Woozy; lose 1 Popularity on Critical Fail. Mark the Attack OR Damage Effect, never both. Conditions, cooldowns and upgrades are manual.","reference":"Core Rulebook p. 180","damage":"","range":"","automation":"manual"},{"id":"powerful-strike","name":"Powerful Strike","kind":"effect","stat":null,"passive":true,"advancement":"special","maxRank":15,"manaCost":null,"description":"Foot Soldier, Noggin Nocker or Pugilism Damage Effect. Multiply base damage dice result by Rank before modifiers. 30-hour cooldown, improving by Rank. Mark Attack OR Effect, never both; resolve conditions and damage at the table.","reference":"Core Rulebook p. 180","damage":"","range":"","automation":"manual"},{"id":"dodge","name":"Dodge","kind":"skill","stat":null,"passive":true,"advancement":"special","maxRank":15,"manaCost":null,"description":"Passive +1 Evade Buff; upgrades at Ranks 5/10/15. Mark only when Evading below Rank 5; later increases require magic/training. Evade bonuses, special marking eligibility and upgrades are adjudicated at the table.","reference":"Core Rulebook p. 190","damage":"","range":"","automation":"manual"},{"id":"gear-head","name":"Gear Head","kind":"skill","stat":"intelligence","passive":false,"advancement":"normal","maxRank":15,"manaCost":null,"description":"Limited Skill from Race/Class/item. Requires Engine Stand attachment to Engineering Table (2,000 gold). Build engines and vehicles using the entry’s crafting rules; resolve costs and upgrades at the table.","reference":"Core Rulebook p. 192","damage":"","range":"","automation":"manual"},{"id":"pathfinder","name":"Pathfinder","kind":"skill","stat":null,"passive":true,"advancement":"none","maxRank":15,"manaCost":null,"description":"HUD map zoom scales with Rank. Rank increases require magic or training. Saferoom/stairwell alerts and other upgrades are adjudicated at the table.","reference":"Core Rulebook p. 195","damage":"","range":"","automation":"manual"},{"id":"ice-blast","name":"Ice Blast","kind":"spell","stat":"intelligence","passive":false,"advancement":"normal","maxRank":15,"manaCost":9,"description":"Ice Attack Spell. Resolve damage and rank upgrades at the table.","reference":"Core Rulebook p. 207","damage":"1d8 + Int Ice","range":"40 feet","automation":"manual"},{"id":"shield-block","name":"Shield Block","kind":"skill","stat":"strength","passive":false,"advancement":"normal","maxRank":15,"manaCost":null,"description":"Interrupt requiring a shield; not against AoE. Spend one Action for separate Checks vs physical Attacks. Success halves damage before DR. Shield wear, timing and upgrades are manual.","reference":"Core Rulebook p. 198","damage":"","range":"","automation":"manual"},{"id":"zone-of-control","name":"Zone of Control","kind":"skill","stat":null,"passive":true,"advancement":"none","maxRank":15,"manaCost":null,"description":"Requires a Reach weapon. Once per round, spend an Action for an Interrupt Attack with Disadvantage when a foe first enters an adjacent space. Resolve timing and rank upgrades at the table.","reference":"Core Rulebook p. 201","damage":"","range":"","automation":"manual"},{"id":"bite","name":"Bite","kind":"attack","stat":"strength","passive":false,"advancement":"normal","maxRank":15,"manaCost":null,"description":"Melee animal Strike; target must have an appendage to clamp onto. Resolve conditions and rank upgrades at the table.","reference":"Core Rulebook p. 177","damage":"1d8 + Str Piercing","range":"Melee","automation":"manual"}]}$selection_catalog$::jsonb);
revoke all on dcc_private.selection_catalog from public,anon,authenticated;

alter table public.dcc_crawlers add column third_floor jsonb not null default '{"reviewed":false,"offers":[],"selected":null}'::jsonb;
alter table public.dcc_crawlers alter column third_floor set default '{"reviewed":true,"offers":[],"selected":null}'::jsonb;
alter table public.dcc_advancement_history drop constraint dcc_advancement_history_operation_check;
alter table public.dcc_advancement_history add constraint dcc_advancement_history_operation_check
 check(operation in ('reconcile','award','authorize','allocate','human-benefit','selection-review','selection-offer','selection-apply'));

create function dcc_private.selection_option(kind text,ident text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare item jsonb;
begin
 select value into item from dcc_private.selection_catalog,lateral jsonb_array_elements(data->kind) where value->>'id'=ident;
 if item is null then raise exception 'Choose a reviewed catalog option.' using errcode='22023';end if;
 return item;
end $$;
create function dcc_private.selection_pair(pair text,skills jsonb,bases jsonb,check_requirements boolean default true) returns jsonb
language plpgsql security definer set search_path='' as $$
declare race jsonb;profession jsonb;k text;n integer;result jsonb:='{}';
begin
 if pair is null or cardinality(string_to_array(pair,'|'))<>2 then raise exception 'Choose a Race/Class pair.' using errcode='22023';end if;
 race:=dcc_private.selection_option('races',split_part(pair,'|',1));profession:=dcc_private.selection_option('classes',split_part(pair,'|',2));
 if profession->>'earthOnly'='true' and race->>'earth'<>'true' then raise exception 'Earth Class requires Earth Race.' using errcode='22023';end if;
 if check_requirements then
  if race->>'requirement'='physical-skill-5' and not exists(select 1 from jsonb_array_elements(skills) where (value->>'rank')::integer>=5 and value->>'stat' in ('strength','dexterity')) then raise exception 'Amazonian requires an existing physical Skill at Rank 5+.' using errcode='22023';end if;
  if profession->>'requirement'='driving-5' and not exists(select 1 from jsonb_array_elements(skills) where lower(value->>'name')='driving' and (value->>'rank')::integer>=5) then raise exception 'Driving Rank 5+ required.' using errcode='22023';end if;
  foreach k in array array['strength','intelligence','constitution','dexterity','charisma'] loop
   n:=(bases#>>array[k,'base'])::integer+(race#>>array['stats',k])::integer+(profession#>>array['stats',k])::integer;
   perform dcc_private.tutorial_int(to_jsonb(n),1,10000);result:=jsonb_set(result,array[k],to_jsonb(n));
  end loop;
 end if;
 return jsonb_build_object('race',race,'class',profession,'bases',result);
end $$;
create function dcc_private.normalize_third_floor(p jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare selected jsonb;v jsonb;ids text[]:=array[]::text[];k text;
begin
 if jsonb_typeof(p) is distinct from 'object' then raise exception 'Invalid Race/Class state.' using errcode='22023';end if;
 if (select count(*) from jsonb_object_keys(p))<>3 or jsonb_typeof(p->'reviewed') is distinct from 'boolean' or jsonb_typeof(p->'offers') is distinct from 'array' then raise exception 'Invalid Race/Class flags.' using errcode='22023';end if;
 if jsonb_array_length(p->'offers')>3 then raise exception 'Offer up to three pairs.' using errcode='22023';end if;
 for v in select value from jsonb_array_elements(p->'offers') loop
  if jsonb_typeof(v) is distinct from 'string' or (v#>>'{}')=any(ids) then raise exception 'Choose distinct offered pairs.' using errcode='22023';end if;
  perform dcc_private.selection_pair(v#>>'{}',null,null,false);ids:=array_append(ids,v#>>'{}');
 end loop;
 selected:=p->'selected';
 if selected is distinct from 'null'::jsonb then
  if jsonb_typeof(selected) is distinct from 'object' then raise exception 'Invalid saved selection.' using errcode='22023';end if;
  foreach k in array array['raceId','classId','raceName','className','notes'] loop
   if jsonb_typeof(selected->k) is distinct from 'string' or length(btrim(selected->>k)) not between 1 and (case when k='notes' then 500 else 100 end) then raise exception 'Check selection identity and notes.' using errcode='22023';end if;
  end loop;
  if selected->>'mode' is null or selected->>'mode' not in ('applied','reconciled') then raise exception 'Invalid benefit mode.' using errcode='22023';end if;
  if (selected->>'raceId'='manual' or selected->>'classId'='manual') and selected->>'mode'<>'reconciled' then raise exception 'Manual identity requires reconciliation.' using errcode='22023';end if;
  if selected->>'raceId'<>'manual' then perform dcc_private.selection_option('races',selected->>'raceId');end if;
  if selected->>'classId'<>'manual' then perform dcc_private.selection_option('classes',selected->>'classId');end if;
  if selected->>'raceId'<>'manual' and selected->>'classId'<>'manual' then perform dcc_private.selection_pair((selected->>'raceId')||'|'||(selected->>'classId'),null,null,false);end if;
  perform dcc_private.tutorial_int(selected->'size',1,8);perform dcc_private.tutorial_int(selected->'move',0,10000);perform dcc_private.tutorial_int(selected->'step',0,10000);
 end if;
 if (p->>'reviewed'='false' and (selected is distinct from 'null'::jsonb or cardinality(ids)>0)) or (selected is distinct from 'null'::jsonb and cardinality(ids)>0) then raise exception 'Inconsistent selection review.' using errcode='22023';end if;
 return p;
end $$;
create function dcc_private.project_third_floor() returns trigger
language plpgsql security definer set search_path='' as $$
declare state jsonb;
begin
 if new.ruleset<>'tutorial-v1' then return new;end if;
 state:=dcc_private.normalize_third_floor(new.third_floor);
 if tg_op='UPDATE' then
  if new.dungeon_floor is distinct from old.dungeon_floor and jsonb_array_length(state->'offers')>0 then
   state:=jsonb_set(state,'{offers}','[]');
   insert into public.dcc_advancement_history(campaign_id,crawler_id,actor_user_id,operation,summary,reason,details)
   values(new.campaign_id,new.id,auth.uid(),'selection-offer','Race/Class offers closed','Floor changed.',jsonb_build_object('fromFloor',old.dungeon_floor,'toFloor',new.dungeon_floor));
  end if;
 end if;
 -- Preserve the old Human flag until GM reconciliation; thereafter selection is authoritative.
 if state->>'reviewed'='true' then
  new.advancement:=jsonb_set(new.advancement,'{humanFavor}',to_jsonb(coalesce(state#>>'{selected,raceId}'='human',false)));
 end if;
 new.third_floor:=state;return new;
end $$;
create trigger dcc_aa_third_floor before insert or update on public.dcc_crawlers for each row execute function dcc_private.project_third_floor();

create function public.dcc_third_floor_action(p_crawler_id uuid,p_expected_version uuid,p_operation text,p_payload jsonb default '{}') returns void
language plpgsql security definer set search_path='' as $$
declare r public.dcc_crawlers%rowtype; state jsonb;selected jsonb:='null';race jsonb;profession jsonb;pair jsonb;
 baseline jsonb;skills jsonb;defenses jsonb;grants jsonb:='{}';choices jsonb;item jsonb;choice jsonb;v jsonb;existing jsonb;definition jsonb;flags jsonb;prior jsonb;
 k text;key text;reason text;summary text;operation text;gm boolean;amount integer;rank_now integer;cap integer;position integer;dr integer;count_choices integer;ids text[]:=array[]::text[];details jsonb;
begin
 if auth.uid() is null then raise exception 'Sign in first.' using errcode='42501';end if;
 select * into r from public.dcc_crawlers where id=p_crawler_id for update;
 if not found then raise exception 'Crawler access denied.' using errcode='42501';end if;
 gm:=dcc_private.is_gm(r.campaign_id);
 if not dcc_private.is_member(r.campaign_id) or (r.owner_user_id is distinct from auth.uid() and not gm) then raise exception 'Crawler access denied.' using errcode='42501';end if;
 if r.ruleset<>'tutorial-v1' then raise exception 'Official crawler required.' using errcode='22023';end if;
 if r.version is distinct from p_expected_version then raise exception 'Crawler changed; refresh.' using errcode='40001';end if;
 if p_operation is null or p_operation not in ('review','offer','select') or jsonb_typeof(p_payload) is distinct from 'object' then raise exception 'Invalid selection action.' using errcode='22023';end if;
 if p_operation<>'select' and not gm then raise exception 'Only the GM reviews and offers choices.' using errcode='42501';end if;
 if r.advancement->>'reconciled'<>'true' then raise exception 'Reconcile level advancement first.' using errcode='22023';end if;
 if p_payload->'confirmed' is distinct from 'true'::jsonb then raise exception 'Confirm existing benefits and table requirements.' using errcode='22023';end if;
 if jsonb_typeof(p_payload->'reason') is distinct from 'string' or length(btrim(p_payload->>'reason')) not between 1 and 500 then raise exception 'Enter a reason of 1 to 500 characters.' using errcode='22023';end if;
 reason:=btrim(p_payload->>'reason');state:=r.third_floor;baseline:=r.stat_baseline;skills:=r.learned_skills;dr:=r.defense_base;defenses:=r.base_typed_defenses;
 details:=jsonb_build_object('previousSelection',state,'previousStats',baseline,'previousSkills',skills,'previousDR',dr,'previousDefenses',defenses);
 if state->'selected' is distinct from 'null'::jsonb then raise exception 'Race/Class benefits are already recorded; do not apply twice.' using errcode='22023';end if;
 if p_operation='review' then
  if state->>'reviewed'='true' then raise exception 'Benefit review already complete.' using errcode='22023';end if;
  if p_payload->>'mode'='none' then
   if r.advancement->>'humanFavor'='true' then raise exception 'Reconcile the previously confirmed Human selection.' using errcode='22023';end if;
   summary:='Reviewed: no Race/Class benefits previously applied';
  elsif p_payload->>'mode'='existing' and r.dungeon_floor>=3 then
   if p_payload->>'raceId'='manual' then
    race:=jsonb_build_object('id','manual','name',p_payload->'raceName','size',p_payload->'size');
   else race:=dcc_private.selection_option('races',p_payload->>'raceId');end if;
   if p_payload->>'classId'='manual' then profession:=jsonb_build_object('id','manual','name',p_payload->'className');
   else profession:=dcc_private.selection_option('classes',p_payload->>'classId');end if;
   selected:=jsonb_build_object('raceId',race->'id','classId',profession->'id','raceName',race->'name','className',profession->'name','size',race->'size',
    'move',coalesce(p_payload->'move','20'::jsonb),'step',coalesce(p_payload->'step','10'::jsonb),'mode','reconciled','notes',reason);
   summary:=format('Reconciled existing %s / %s; no bonuses reapplied',race->>'name',profession->>'name');
  else raise exception 'Existing selection review requires Floor 3 or deeper.' using errcode='22023';end if;
  state:=jsonb_build_object('reviewed',true,'offers','[]'::jsonb,'selected',selected);operation:='selection-review';
 else
  if state->>'reviewed'<>'true' then raise exception 'Review existing benefits first.' using errcode='22023';end if;
  if p_operation='offer' then
   if jsonb_typeof(p_payload->'offers') is distinct from 'array' then raise exception 'Choose offered pairs.' using errcode='22023';end if;
   if jsonb_array_length(p_payload->'offers')>0 and r.dungeon_floor<3 then raise exception 'Selection requires Floor 3 or deeper.' using errcode='22023';end if;
   for v in select value from jsonb_array_elements(p_payload->'offers') loop
    if jsonb_typeof(v) is distinct from 'string' then raise exception 'Choose catalog pairs.' using errcode='22023';end if;
    perform dcc_private.selection_pair(v#>>'{}',skills,baseline,true);
   end loop;
   state:=jsonb_set(state,'{offers}',p_payload->'offers');summary:='GM updated Race/Class offers';operation:='selection-offer';
  else
   key:=p_payload->>'pair';
   if r.dungeon_floor<3 or jsonb_typeof(p_payload->'pair') is distinct from 'string' or not (state->'offers' ? key) then raise exception 'Select a currently offered pair on Floor 3 or deeper.' using errcode='22023';end if;
   pair:=dcc_private.selection_pair(key,skills,baseline,true);race:=pair->'race';profession:=pair->'class';choices:=p_payload->'choices';
   if jsonb_typeof(choices) is distinct from 'object' then raise exception 'Enter Class benefit choices.' using errcode='22023';end if;
   if (select count(*) from jsonb_object_keys(choices))<>jsonb_array_length(profession->'choices') then raise exception 'Complete exactly the Class choices.' using errcode='22023';end if;
   foreach k in array array['strength','intelligence','constitution','dexterity','charisma'] loop baseline:=jsonb_set(baseline,array[k,'base'],pair#>array['bases',k]);end loop;
   for item in select value from jsonb_array_elements(jsonb_build_array(race,profession)) loop
    for k,v in select * from jsonb_each(item->'skills') loop grants:=jsonb_set(grants,array[k],to_jsonb(coalesce((grants->>k)::integer,0)+(v#>>'{}')::integer));end loop;
   end loop;
   for choice in select value from jsonb_array_elements(profession->'choices') loop
    item:=choices->(choice->>'id');
    if jsonb_typeof(item) is distinct from 'array' then raise exception 'Choose the Class benefits.' using errcode='22023';end if;
    if jsonb_array_length(item)<>(choice->>'count')::integer then raise exception 'Wrong number of Class choices.' using errcode='22023';end if;
    ids:=array[]::text[];
    for v in select value from jsonb_array_elements(item) loop
     k:=v#>>'{}';
     if jsonb_typeof(v) is distinct from 'string' or k=any(ids) or not (choice->'ids' ? k) then raise exception 'Choose different listed Class benefits.' using errcode='22023';end if;
     ids:=array_append(ids,k);grants:=jsonb_set(grants,array[k],to_jsonb(coalesce((grants->>k)::integer,0)+(choice->>'bonus')::integer));
    end loop;
   end loop;
   for k,v in select * from jsonb_each(grants) loop
    definition:=dcc_private.selection_option('abilities',k);amount:=(v#>>'{}')::integer;
    if k='heal' then raise exception 'Tutorial Heal is protected.' using errcode='22023';end if;
    existing:=null;position:=null;
    select value,ordinality::integer-1 into existing,position from jsonb_array_elements(skills) with ordinality where value->>'id'=k or lower(value->>'name')=lower(definition->>'name') limit 1;
    if existing is not null then
     if existing->>'kind'<>definition->>'kind' or lower(existing->>'name')<>lower(definition->>'name') then raise exception 'Review conflicting learned ability definition.' using errcode='22023';end if;
     cap:=(existing->>'maxRank')::integer;rank_now:=greatest((existing->>'rank')::integer,least(10,cap,(existing->>'rank')::integer+amount));
     existing:=jsonb_set(existing,'{rank}',to_jsonb(rank_now));
     if rank_now>=least(15,cap) then existing:=jsonb_set(existing,'{marked}','false');end if;
     skills:=jsonb_set(skills,array[position::text],existing);
    else skills:=skills||jsonb_build_array(definition||jsonb_build_object('rank',least(10,amount),'marked',false,'origin','gm'));end if;
   end loop;
   dr:=dr+(race->>'dr')::integer+(profession->>'dr')::integer;perform dcc_private.tutorial_int(to_jsonb(dr),0,10000);
   for item in select value from jsonb_array_elements(jsonb_build_array(race->'defenses',profession->'defenses')) loop
    for k,flags in select * from jsonb_each(item) loop
     prior:=defenses->k;
     defenses:=jsonb_set(defenses,array[k],jsonb_build_object('resistant',coalesce((prior->>'resistant')::boolean,false) or (flags->>'resistant')::boolean,'vulnerable',coalesce((prior->>'vulnerable')::boolean,false) or (flags->>'vulnerable')::boolean,'immune',coalesce((prior->>'immune')::boolean,false) or (flags->>'immune')::boolean));
    end loop;
   end loop;
   selected:=jsonb_build_object('raceId',race->'id','classId',profession->'id','raceName',race->'name','className',profession->'name','size',race->'size','move',20,'step',10,'mode','applied','notes',reason);
   state:=jsonb_build_object('reviewed',true,'offers','[]'::jsonb,'selected',selected);
   summary:=format('Selected %s / %s; supported benefits applied once',race->>'name',profession->>'name');operation:='selection-apply';
   details:=details||jsonb_build_object('choices',choices,'grants',grants);
  end if;
 end if;
 perform dcc_private.normalize_third_floor(state);
 -- Existing projections preserve Health, clamp Mana only if its maximum falls, and clean no valid links.
 update public.dcc_crawlers set third_floor=state,stat_baseline=baseline,learned_skills=skills,defense_base=dr,base_typed_defenses=defenses,version=gen_random_uuid() where id=r.id;
 insert into public.dcc_advancement_history(campaign_id,crawler_id,actor_user_id,operation,summary,reason,details)
 values(r.campaign_id,r.id,auth.uid(),operation,summary,reason,details||jsonb_build_object('selection',state,'floor',r.dungeon_floor));
end $$;

alter function public.dcc_advancement_action(uuid,uuid,text,jsonb) set schema dcc_private;
alter function dcc_private.dcc_advancement_action(uuid,uuid,text,jsonb) rename to advancement_before_selection;
create function public.dcc_advancement_action(p_crawler_id uuid,p_expected_version uuid,p_operation text,p_payload jsonb default '{}') returns void
language plpgsql security definer set search_path='' as $$
begin
 if p_operation='human-benefit' then
  if auth.uid() is null or not exists(select 1 from public.dcc_crawlers where id=p_crawler_id and dcc_private.is_gm(campaign_id)) then raise exception 'Only the GM manages selection.' using errcode='42501';end if;
  raise exception 'Use Third Floor Race/Class selection to confirm Human benefits.' using errcode='22023';
 end if;
 perform dcc_private.advancement_before_selection(p_crawler_id,p_expected_version,p_operation,p_payload);
end $$;
update public.dcc_crawlers set version=gen_random_uuid() where ruleset='tutorial-v1';
revoke all on function dcc_private.selection_option(text,text),dcc_private.selection_pair(text,jsonb,jsonb,boolean),dcc_private.normalize_third_floor(jsonb),dcc_private.project_third_floor(),dcc_private.advancement_before_selection(uuid,uuid,text,jsonb) from public,anon,authenticated;
revoke all on function public.dcc_third_floor_action(uuid,uuid,text,jsonb),public.dcc_advancement_action(uuid,uuid,text,jsonb) from public,anon,authenticated;
grant execute on function public.dcc_third_floor_action(uuid,uuid,text,jsonb),public.dcc_advancement_action(uuid,uuid,text,jsonb) to authenticated;
notify pgrst,'reload schema';
commit;
